// Des: Optional AI text drafts: Claude Code CLI first, local llama.cpp as backup
// Flo: only when smar_mode_enab > try each tool in smar_chai_orde > clau = run `claude -p` with a timeout > llam = POST to a loopback llama.cpp server > first good text wins
// I/O: prompt text (caller) > drafted text (arena owned); error AiFail when every tool fails; never leaves the machine except via the owner's own Claude CLI
// ===================================================================
const std = @import("std"); const net = std.Io.net; const mem = std.mem; const task = @import("ru-task-runn.zig");
const CF = .{ .maxo = 65536, .maxh = 1 << 20, .npre = 160, .loc1 = "127.0.0.1", .loc2 = "localhost", .path = "/completion" };
pub fn urlSplit(urlz: []const u8) !struct { port: u16, pref: []const u8 } { const rest = if (mem.startsWith(u8, urlz, "http://")) urlz[7..] else return error.AiFail; const end = mem.findScalar(u8, rest, '/') orelse rest.len; const hp = rest[0..end]; const col = mem.findScalar(u8, hp, ':') orelse return error.AiFail; const host = hp[0..col]; if (!mem.eql(u8, host, CF.loc1) and !mem.eql(u8, host, CF.loc2)) return error.AiFail; const port = std.fmt.parseInt(u16, hp[col + 1 ..], 10) catch return error.AiFail; return .{ .port = port, .pref = rest[end..] }; }
pub fn contentOf(aren: std.mem.Allocator, body: []const u8) ![]const u8 { const val = std.json.parseFromSliceLeaky(std.json.Value, aren, body, .{ .allocate = .alloc_always }) catch return error.AiFail; if (val != .object) return error.AiFail; const con = val.object.get("content") orelse return error.AiFail; if (con != .string) return error.AiFail; const trm = mem.trim(u8, con.string, " \r\n\t"); if (trm.len == 0) return error.AiFail; return trm; }
fn runClaude(ctx: *task.Ctx, prompt: []const u8) ![]const u8 { const res = std.process.run(ctx.gpaz, ctx.iozz, .{ .argv = &.{ ctx.conf.smar_clau_exec, "-p", prompt }, .stdout_limit = .limited(CF.maxo), .stderr_limit = .limited(CF.maxo), .timeout = .{ .duration = .{ .raw = .fromMilliseconds(@as(i64, ctx.conf.smar_time_seco) * 1000), .clock = .awake } } }) catch return error.AiFail; defer ctx.gpaz.free(res.stdout); defer ctx.gpaz.free(res.stderr); switch (res.term) { .exited => |cod| if (cod != 0) return error.AiFail, else => return error.AiFail } const trm = mem.trim(u8, res.stdout, " \r\n\t"); if (trm.len == 0) return error.AiFail; return ctx.aren.dupe(u8, trm); }
fn postLoc(ctx: *task.Ctx, port: u16, path: []const u8, body: []const u8) ![]u8 { var addr = net.IpAddress.parse(CF.loc1, port) catch return error.AiFail; const strm = addr.connect(ctx.iozz, .{ .mode = .stream }) catch return error.AiFail; defer strm.close(ctx.iozz); var wbuf: [1024]u8 = undefined; var wrt = strm.writer(ctx.iozz, &wbuf); wrt.interface.print("POST {s} HTTP/1.1\r\nHost: 127.0.0.1:{d}\r\nContent-Type: application/json\r\nContent-Length: {d}\r\nConnection: close\r\n\r\n", .{ path, port, body.len }) catch return error.AiFail; wrt.interface.writeAll(body) catch return error.AiFail; wrt.interface.flush() catch return error.AiFail; var rbuf: [4096]u8 = undefined; var rdr = strm.reader(ctx.iozz, &rbuf); const rd = &rdr.interface; const first = rd.takeDelimiterInclusive('\n') catch return error.AiFail; if (mem.find(u8, first, " 200") == null) return error.AiFail; while (true) { const line = rd.takeDelimiterInclusive('\n') catch return error.AiFail; if (line.len <= 2) break; } return rd.allocRemaining(ctx.aren, .limited(CF.maxh)) catch return error.AiFail; }
fn runLlama(ctx: *task.Ctx, prompt: []const u8) ![]const u8 { const sp = try urlSplit(ctx.conf.smar_llam_urlz); const body = try std.json.Stringify.valueAlloc(ctx.aren, .{ .prompt = prompt, .n_predict = @as(u32, 120), .stream = false }, .{}); const path = if (sp.pref.len > 1) sp.pref else CF.path; const rsp = try postLoc(ctx, sp.port, path, body); return contentOf(ctx.aren, rsp); }
pub fn draftChain(ctx: *task.Ctx, prompt: []const u8) anyerror![]const u8 { if (!ctx.conf.smar_mode_enab) return error.AiFail; for (ctx.conf.smar_chai_orde) |tool| { const got = if (mem.eql(u8, tool, "clau")) runClaude(ctx, prompt) else runLlama(ctx, prompt); if (got) |txt| return txt else |_| {} } return error.AiFail; }
